1	package govflow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// makeDirSyncFail 让状态文件所在目录可写可进入但不可读（0o300）：临时文件
13	// 写入、fsync 与原子改名仍然成功，只有 syncDir 打开目录失败，从而确定性地
14	// 复现“状态文件已替换成功、随后目录同步失败”。返回恢复函数。
15	func makeDirSyncFail(t *testing.T, statePath string) {
16		t.Helper()
17		dir := filepath.Dir(statePath)
18		if err := os.Chmod(dir, 0o300); err != nil {
19			t.Fatalf("chmod dir: %v", err)
20		}
21		t.Cleanup(func() { _ = os.Chmod(dir, 0o700) })
22	}
23	
24	// makeDirUnwritable 让状态文件所在目录不可写（0o555）：提交在状态文件替换
25	// 之前（创建临时文件）就失败，复现“尚未写入”的保存失败。恢复由 Cleanup 负责。
26	func makeDirUnwritable(t *testing.T, statePath string) {
27		t.Helper()
28		dir := filepath.Dir(statePath)
29		if err := os.Chmod(dir, 0o555); err != nil {
30			t.Fatalf("chmod dir: %v", err)
31		}
32		t.Cleanup(func() { _ = os.Chmod(dir, 0o700) })
33	}
34	
35	func assertReceiptShape(t *testing.T, r *Receipt, id string, executedAt, order int64, action string, treasuryBefore, treasuryAfter, recipientBefore, recipientAfter int64) {
36		t.Helper()
37		if r == nil {
38			t.Fatal("receipt is nil")
39		}
40		if r.ProposalID != id || r.ExecutedAt != executedAt || r.Order != order {
41			t.Fatalf("receipt header = %+v, want proposal=%s executed_at=%d order=%d", r, id, executedAt, order)
42		}
43		if len(r.Actions) != 1 {
44			t.Fatalf("receipt actions = %+v, want exactly one", r.Actions)
45		}
46		ar := r.Actions[0]
47		if ar.Index != 0 || ar.Action != action {
48			t.Fatalf("action receipt = %+v, want index 0 action %q", ar, action)
49		}
50		if ar.Treasury.Before != treasuryBefore || ar.Treasury.After != treasuryAfter {
51			t.Fatalf("treasury update = %d -> %d, want %d -> %d",
52				ar.Treasury.Before, ar.Treasury.After, treasuryBefore, treasuryAfter)
