372	func assertMemberViews(t *testing.T, prefix string, got, want map[string]MemberView) {
373		t.Helper()
374		if len(got) != len(want) {
375			t.Fatalf("%s: member count=%d want %d", prefix, len(got), len(want))
376		}
377		for id, w := range want {
378			g, ok := got[id]
379			if !ok {
380				t.Errorf("%s: member %s missing from view", prefix, id)
381				continue
382			}
383			if !equalStrings(g.Path, w.Path) {
384				t.Errorf("%s: member %s path=%v want %v", prefix, id, g.Path, w.Path)
385			}
386			// 路径的相邻成员必须对应一次真实委托；无重复成员；首尾为本人和最终代表。
387			if len(g.Path) == 0 || g.Path[0] != id || g.Path[len(g.Path)-1] != g.Delegate {
388				t.Errorf("%s: member %s path %v inconsistent with self/final representative %q", prefix, id, g.Path, g.Delegate)
389			}
390			if g.Delegate != w.Delegate {
391				t.Errorf("%s: member %s delegate=%q want %q", prefix, id, g.Delegate, w.Delegate)
392			}
393			if g.Direct != w.Direct {
394				t.Errorf("%s: member %s direct_to=%q want %q", prefix, id, g.Direct, w.Direct)
395			}
396			if g.Weight != w.Weight {
397				t.Errorf("%s: member %s weight=%d want %d", prefix, id, g.Weight, w.Weight)
398			}
399		}
400	}
