1	package govflow
2	
3	import (
4		"errors"
5		"os"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// passVote 让一项带真实委托的投票提案由最终代表在窗口内完成投票与计票：
12	// alice 归集 bob、carol 的委托权重（300+200+100=600）投赞成，dave（400）投
13	// 反对；参与量 1000 达到法定人数 600 且赞成严格多于反对，首次计票结论为 passed。
14	// 全部时间由调用方给定，不使用真实时钟。
15	func passVote(t *testing.T, store *Store, id string, voteFor, voteAgainst, tallyAt int64) {
16		t.Helper()
17		// 已委托出去的成员不能代替最终代表投票：入口必须明确拒绝，
18		// 证明通过结论只能由最终代表本人的票据产生。
19		if _, err := store.CastVote(id, "bob", true, voteFor); !errors.Is(err, ErrVoteRejected) {
20			t.Fatalf("delegated member bob voted directly: %v", err)
21		}
22		b, err := store.CastVote(id, "alice", true, voteFor)
23		if err != nil {
24			t.Fatalf("alice vote: %v", err)
25		}
26		if b.Weight != 600 {
27			t.Fatalf("alice delegated ballot weight=%d, want 600", b.Weight)
28		}
29		if _, err := store.CastVote(id, "dave", false, voteAgainst); err != nil {
30			t.Fatalf("dave vote: %v", err)
31		}
32		res, err := store.TallyVote(id, tallyAt)
33		if err != nil {
34			t.Fatalf("tally %s: %v", id, err)
35		}
36		if !res.Passed || res.ForWeight != 600 || res.AgainstWeight != 400 || res.Turnout != 1000 {
37			t.Fatalf("%s tally=%+v, want passed for=600 against=400 turnout=1000", id, res)
38		}
39	}
40	
41	// assertGovernanceUnchanged 断言执行失败后提案查询仍展示 passed，且成员原始
42	// 权重、完整委托路径、逐票代表与首次投票时间、首次计票权重与时间都保持原值：
43	// 失败不得删除票据、不得重新生成计票结论。
44	func assertGovernanceUnchanged(t *testing.T, store *Store, id string, actions []string, forAt, againstAt, tallyAt int64) {
45		t.Helper()
46		v, ok, err := store.VoteProposal(id)
47		if err != nil || !ok {
48			t.Fatalf("VoteProposal(%s): ok=%v err=%v", id, ok, err)
49		}
50		if v.State != "passed" || v.Source != "vote" {
51			t.Fatalf("%s state=%s source=%s, want passed/vote", id, v.State, v.Source)
52		}
53		if v.Quorum != 600 || v.TotalWeight != 1000 {
54			t.Fatalf("%s quorum=%d total=%d, want 600/1000", id, v.Quorum, v.TotalWeight)
55		}
56		if !sameActions(v.Actions, actions) {
57			t.Fatalf("%s actions=%v, want original raw actions %v", id, v.Actions, actions)
58		}
59		// 成员原始权重与完整委托路径逐字保留（bob→alice、carol→alice）。
60		wantWeight := map[string]int64{"alice": 300, "bob": 200, "carol": 100, "dave": 400}
61		wantPath := map[string][]string{
62			"alice": {"alice"},
63			"bob":   {"bob", "alice"},
64			"carol": {"carol", "alice"},
65			"dave":  {"dave"},
66		}
67		if len(v.Members) != 4 {
68			t.Fatalf("%s members=%+v, want 4", id, v.Members)
69		}
70		for _, m := range v.Members {
71			if m.Weight != wantWeight[m.ID] {
72				t.Fatalf("%s member %s weight=%d, want %d", id, m.ID, m.Weight, wantWeight[m.ID])
73			}
74			if !equalStrings(m.Path, wantPath[m.ID]) {
75				t.Fatalf("%s member %s path=%v, want %v", id, m.ID, m.Path, wantPath[m.ID])
76			}
77		}
78		// 最终代表：alice 归集 bob、carol；alice 与 dave 各自代表自己。
79		gotPaths := memberPaths(v)
80		for id2, wantHead := range map[string]string{"alice": "alice", "bob": "alice", "carol": "alice", "dave": "dave"} {
81			if gotPaths[id2].Delegate != wantHead {
82				t.Fatalf("%s member %s final representative=%s, want %s", id, id2, gotPaths[id2].Delegate, wantHead)
83			}
84		}
85		// 逐票代表、票重、选择与首次投票时间保持首次记录（按首次投票先后）。
86		if len(v.Ballots) != 2 {
87			t.Fatalf("%s ballots=%+v, want 2", id, v.Ballots)
88		}
89		b0, b1 := v.Ballots[0], v.Ballots[1]
90		if b0.Representative != "alice" || b0.Weight != 600 || !b0.Support || b0.VotedAt != forAt {
91			t.Fatalf("%s ballot 0=%+v, want alice/600/for/%d", id, b0, forAt)
92		}
93		if b1.Representative != "dave" || b1.Weight != 400 || b1.Support || b1.VotedAt != againstAt {
94			t.Fatalf("%s ballot 1=%+v, want dave/400/against/%d", id, b1, againstAt)
95		}
96		// 首次计票权重与时间保持原值，查询结论仍为通过。
97		if v.Tally == nil {
98			t.Fatalf("%s tally missing after failed execution", id)
99		}
100		if v.Tally.ForWeight != 600 || v.Tally.AgainstWeight != 400 || v.Tally.Turnout != 1000 ||
101			!v.Tally.Passed || v.Tally.TalliedAt != tallyAt {
102			t.Fatalf("%s tally=%+v, want for=600 against=400 turnout=1000 passed tallied=%d",
103				id, v.Tally, tallyAt)
104		}
105		// 再次计票仍返回首次结论，而不是重新生成。
106		again, err := store.TallyVote(id, tallyAt+999)
107		if err != nil || again.TalliedAt != tallyAt || again.ForWeight != 600 || again.AgainstWeight != 400 {
108			t.Fatalf("%s repeat tally=%+v err=%v, want first verdict at %d", id, again, err, tallyAt)
109		}
110	}
111	
112	// TestPassedVoteProposalExecutionFailureFullyReverts：投票通过提案在时间锁到期
113	// 执行一组有序转账，后面的动作才暴露出问题（格式错误 / 前序消耗导致余额不足）时，
114	// 整项拒绝必须固定下来——不能只看到返回了错误，也不能用 register 直接登记的
115	// 提案冒充真正经过投票与计票的提案。失败后资金、票据、委托与首次计票结论都不得
116	// 发生部分变化，失败不产生成功凭据，也不消耗执行机会；合法且余额足够的投票提案
117	// 仍能正常转账并转为 executed。
118	func TestPassedVoteProposalExecutionFailureFullyReverts(t *testing.T) {
119		store, path := openTempStore(t, 1000)
120		defer store.Close()
121	
122		// 此前已有另一项提案的成功凭据（order=0），并给两个收款账户留下既有余额：
123		// priora=40、priorb=60，资金库剩 900。失败后这份凭据的内容与提交次序必须原样。
124		mustRegister(t, store, "gip-prior", 0, "transfer:priora:40", "transfer:priorb:60")
125		if _, err := store.Execute("gip-prior", 0); err != nil {
126			t.Fatalf("execute prior receipt: %v", err)
127		}
128		priorReceipt, ok, err := store.Receipt("gip-prior")
129		if err != nil || !ok {
130			t.Fatalf("prior receipt: ok=%v err=%v", ok, err)
131		}
132		if bal, _ := store.TreasuryBalance(); bal != 900 {
133			t.Fatalf("setup treasury=%d, want 900", bal)
134		}
135	
136		// 失败提案一：余额不足必须由前序转账消耗后触发。
137		// 资金库 900，前 3 笔共支出 600（前两笔连续发给同一新账户 newa，第三笔发给
138		// 已有余额的 priora），第 4 笔 400 在剩余 300 上才不足——它本身（400）并未
139		// 超过执行前资金库（900），不是“第一笔就超额”的退化情形。
140		fundActions := []string{
141			"transfer:newa:100",
142			"transfer:newa:200",
143			"transfer:priora:300",
144			"transfer:newb:400",
145		}
146		fundInput := baseVoteInput("gip-fail-funds")
147		fundInput.Actions = fundActions
148		mustCreateVote(t, store, fundInput)
149		passVote(t, store, "gip-fail-funds", 150, 160, 200)
150	
151		// 失败提案二：格式错误按现有行为在创建时允许保存原文，执行时才拒绝。
152		// 前两笔同样连续发给同一新账户 newc，第三笔发给已有余额的 priorb。
153		badText := "withdraw:newd:9"
154		formActions := []string{
155			"transfer:newc:100",
156			"transfer:newc:150",
157			"transfer:priorb:50",
158			badText,
159		}
160		formInput := baseVoteInput("gip-fail-form")
161		formInput.Actions = formActions
162		mustCreateVote(t, store, formInput)
163		passVote(t, store, "gip-fail-form", 150, 160, 200)
164	
165		// register 与投票共用编号：直接登记不能覆盖或冒充真正投票+计票的提案。
166		if _, err := store.Register("gip-fail-funds", 300, fundActions); !errors.Is(err, ErrProposalConflict) {
167			t.Fatalf("register over voting proposal err=%v, want ErrProposalConflict", err)
168		}
169	
170		// 时间锁到期执行：两项都在后面的动作上失败。状态文件在失败前后必须逐字节一致
171		// （失败路径根本不得提交）。
172		beforeBytes, err := os.ReadFile(path)
173		if err != nil {
174			t.Fatal(err)
175		}
176		_, fundErr := store.Execute("gip-fail-funds", 300)
177		if !errors.Is(fundErr, ErrExecutionRejected) || errors.Is(fundErr, ErrInvalidAction) {
178			t.Fatalf("funds err=%v, want ErrExecutionRejected without ErrInvalidAction", fundErr)
179		}
180		if !strings.Contains(fundErr.Error(), "insufficient treasury balance at action 3") ||
181			!strings.Contains(fundErr.Error(), "treasury=300") || !strings.Contains(fundErr.Error(), "amount=400") {
182			t.Fatalf("funds error must classify cause and locate action 3: %v", fundErr)
183		}
184		_, formErr := store.Execute("gip-fail-form", 300)
185		if !errors.Is(formErr, ErrExecutionRejected) || !errors.Is(formErr, ErrInvalidAction) {
186			t.Fatalf("form err=%v, want both ErrExecutionRejected and ErrInvalidAction", formErr)
187		}
188		if !strings.Contains(formErr.Error(), `action 3 ("withdraw:newd:9")`) {
189			t.Fatalf("form error must locate action 3 with original text: %v", formErr)
190		}
191		afterBytes, err := os.ReadFile(path)
192		if err != nil {
193			t.Fatal(err)
194		}
195		if string(afterBytes) != string(beforeBytes) {
196			t.Fatal("failed executions wrote partial changes to the state file")
197		}
198	
199		// 失败不消耗执行机会：再次执行仍是同一类整项拒绝，而不是成功或找不到提案。
200		if _, err := store.Execute("gip-fail-funds", 301); !errors.Is(err, ErrExecutionRejected) ||
201			!strings.Contains(err.Error(), "action 3") {
202			t.Fatalf("retry after funds failure err=%v", err)
203		}
204		if _, err := store.Execute("gip-fail-form", 301); !errors.Is(err, ErrInvalidAction) {
205			t.Fatalf("retry after form failure err=%v", err)
206		}
207	
208		// ---- 余额查询必须与执行前完全一致 ----
209		snap, err := store.BalanceSnapshot()
210		if err != nil {
211			t.Fatal(err)
212		}
213		if snap.Treasury != 900 {
214			t.Fatalf("treasury changed after failed executions: %d, want 900", snap.Treasury)
215		}
216		// 原本已有余额的收款账户没有增款。
217		if snap.Balances["priora"] != 40 {
218			t.Fatalf("existing priora balance=%d, want 40", snap.Balances["priora"])
219		}
220		if snap.Balances["priorb"] != 60 {
221			t.Fatalf("existing priorb balance=%d, want 60", snap.Balances["priorb"])
222		}
223		// 前序动作涉及的新账户不能留下余额记录：即使前两笔发给同一个账户，
224		// 也不能留下其中一笔的变化；键本身不得出现在余额表中。
225		for _, acct := range []string{"newa", "newb", "newc", "newd"} {
226			if bal, ok := snap.Balances[acct]; ok || bal != 0 {
227				t.Fatalf("new account %s left a balance record: %d", acct, bal)
228			}
229			if bal, _ := store.Balance(acct); bal != 0 {
230				t.Fatalf("Balance(%s)=%d, want 0", acct, bal)
231			}
232		}
233		if len(snap.Balances) != 2 {
234			t.Fatalf("balances table=%+v, want only priora/priorb", snap.Balances)
235		}
236	
237		// ---- 提案仍展示 passed；成员、委托路径、逐票与首次计票结论保持原值 ----
238		assertGovernanceUnchanged(t, store, "gip-fail-funds", fundActions, 150, 160, 200)
239		assertGovernanceUnchanged(t, store, "gip-fail-form", formActions, 150, 160, 200)
240	
241		// 两项失败提案都没有成功执行凭据；此前的凭据仍是唯一一份，内容与次序不变。
242		if r, ok, _ := store.Receipt("gip-fail-funds"); ok || r != nil {
243			t.Fatalf("funds failure left a receipt: %+v", r)
244		}
245		if r, ok, _ := store.Receipt("gip-fail-form"); ok || r != nil {
246			t.Fatalf("form failure left a receipt: %+v", r)
247		}
248		receipts, err := store.Receipts()
249		if err != nil || len(receipts) != 1 {
250			t.Fatalf("receipts=%v err=%v, want exactly the prior one", receipts, err)
251		}
252		if !reflect.DeepEqual(receipts[0], priorReceipt) {
253			t.Fatalf("prior receipt changed:\nbefore=%+v\nafter =%+v", priorReceipt, receipts[0])
254		}
255	
256		// 重开状态文件：失败提案仍是 passed、无凭据、治理记录原值、余额原值。
257		if err := store.Close(); err != nil {
258			t.Fatal(err)
259		}
260		reopened, err := Open(path)
261		if err != nil {
262			t.Fatalf("reopen after failed executions: %v", err)
263		}
264		defer reopened.Close()
265		if bal, _ := reopened.TreasuryBalance(); bal != 900 {
266			t.Fatalf("treasury after reopen=%d, want 900", bal)
267		}
268		reSnap, _ := reopened.BalanceSnapshot()
269		if len(reSnap.Balances) != 2 || reSnap.Balances["priora"] != 40 || reSnap.Balances["priorb"] != 60 {
270			t.Fatalf("balances after reopen=%+v", reSnap.Balances)
271		}
272		assertGovernanceUnchanged(t, reopened, "gip-fail-funds", fundActions, 150, 160, 200)
273		assertGovernanceUnchanged(t, reopened, "gip-fail-form", formActions, 150, 160, 200)
274		reopenedPrior, ok, err := reopened.Receipt("gip-prior")
275		if err != nil || !ok || !reflect.DeepEqual(reopenedPrior, priorReceipt) {
276			t.Fatalf("prior receipt after reopen differs: ok=%v err=%v", ok, err)
277		}
278		if rs, _ := reopened.Receipts(); len(rs) != 1 || rs[0].Order != 0 || rs[0].ProposalID != "gip-prior" {
279			t.Fatalf("receipt order changed after failed executions: %+v", rs)
280		}
281	
282		// ---- 成功对照：动作合法且余额足够的投票通过提案仍正常转账并转为已执行 ----
